import{z as A,x as s,o as t,c as d,q as o,j as i,D as E,d as n,s as r,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"思考预算与自适应思考","description":"","frontmatter":{"title":"思考预算与自适应思考","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/thinking-budget-adaptive.md","filePath":"llm/thinking-budget-adaptive.md","lastUpdated":1791413859000}'),p={name:"llm/thinking-budget-adaptive.md"};function m(D,a,h,u,f,k){const l=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="思考预算与自适应思考" tabindex="-1">思考预算与自适应思考 <a class="header-anchor" href="#思考预算与自适应思考" aria-label="Permalink to &quot;思考预算与自适应思考&quot;">​</a></h1><div class="epigraph"><p>同一套权重，多给一些推理 token 往往更准；预算从哪来、谁来停，是测试时缩放的旋钮。</p><footer>—— OpenAI o1 / o3 的思考时间；Snell 等测试时计算；Muennighoff 等 s1 的预算强迫</footer></div><p><a href="/llm/rl-scaling-laws">上一课</a>把训练 RL 算力与金标画在一张图上。本单元改画<strong>一次推理的长度</strong>。缺口是：R1 / o1 类模型会自己长链，但产品需要上限；太短截断推理，太长烧钱。<a href="/llm/deepseek-r1">DeepSeek-R1</a> 已写行为表象。本课写预算与自适应：何时想够了。接到混合思考、过度思考。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练侧 <a href="/llm/grpo">GRPO</a> 用终局 \\(R\\)，长度涨是因为长搜索更容易撞对。推理侧若无上限，延迟与 KV 爆。预算 \\(B\\)：思维 token 的硬顶。自适应：模型或控制器在 \\(\\lt B\\) 时决定 EOS。s1 的 budget forcing 在还没停时插入「Wait」强迫续写，显示额外 token 仍能抬分。o1 产品把思考时间当用户可见档位。</p><p>自适应失败有两头：简单题也写满 \\(B\\)（过度思考，后课）；难题在预算内乱收尾（过长过滤课的截断问题在推理时再现）。</p><h3 id="预算是策略的一部分" tabindex="-1">预算是策略的一部分 <a class="header-anchor" href="#预算是策略的一部分" aria-label="Permalink to &quot;预算是策略的一部分&quot;">​</a></h3><p>训练若从不见 \\(B\\)，推理突然截断，分布外。应在 RL 中随机 \\(B\\) 或对超 \\(B\\) 塑形，使策略会收束。与训练-推理精度不匹配同类：解码约束属于 \\(\\pi_{\\mathrm{beh}}\\)。</p><p><span class="marginnote">术语翻译：思考预算（budget）就是给模型的「草稿纸页数上限」——思维链最多写 \\(B\\) 个 token，写满就必须给答案。s1 的 budget forcing 则相反：模型想提前收工时，硬塞一个「Wait」逼它继续写，用来验证多想一步还能不能涨分。</span></p><p><span class="marginnote">隐藏思维 + 用户可见摘要时，预算计的是隐藏链。摘要器另占 token，不要混进 \\(B\\) 的 SLA。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬顶：到达 \\(B\\) 插入收束提示或强制 boxed。自适应：用内部置信、自检头、或「答案已稳定」规则早停。训练：过长软惩罚（DAPO）+ 随机长度上限，让策略在多档 \\(B\\) 下都还能得 \\(R\\)。评测：同一题扫 \\(B\\)，画准确率–延迟帕累托，对应 Snell 的测试时计算曲线。</p>',12)),(t(),i(B,null,{default:E(()=>[r(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20TH%5B%22%E6%80%9D%E7%BB%B4%20token%22%5D%0A%20%20TH%20--%3E%20DEC%7B%22%E6%9C%AA%E5%88%B0%20B%20%E4%B8%94%E6%9C%AA%E7%A1%AE%E4%BF%A1%22%7D%0A%20%20DEC%20--%3E%7C%E7%BB%A7%E7%BB%AD%7C%20TH%0A%20%20DEC%20--%3E%7C%E5%81%9C%7C%20ANS%5B%22%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%22%5D%0A%20%20B%5B%22%E9%A2%84%E7%AE%97%20B%22%5D%20--%3E%20DEC%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与并行思考（后课）对照：预算是串行加长；并行是多样本。两者都花测试时 FLOPs，可互换一段。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"额外 token 提供串行工作记忆（必要性论点，见 CoT monitorability 课）。自适应要估计边际收益。模型的口头「已经想清楚」不可靠（诚实课）。更好的是：答案跨续写稳定、或校验器可中途调用（工具课）。无校验器时，早停偏冒险。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"RL 若奖励只看对错、不看 \\(B\\)，自适应不会自己省 token。必须把预算写进 \\(R\\) 或多档训练。")],-1)),a[7]||(a[7]=e("p",null,"预算与难度错配的两种失败：",-1)),(t(),i(B,null,{default:E(()=>[r(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%7B%22%E9%A2%84%E7%AE%97%20B%20%E4%B8%8E%E9%A2%98%E7%9B%AE%E9%9A%BE%E5%BA%A6%E5%8C%B9%E9%85%8D%3F%22%7D%20--%3E%20E%5B%22%E7%AE%80%E5%8D%95%E9%A2%98%3A%20%E5%BE%88%E6%97%A9%E5%B0%B1%E8%83%BD%E7%AD%94%E5%AF%B9%22%5D%0A%20%20E%20--%3E%20OVER%5B%22%E4%BB%8D%E5%86%99%E6%BB%A1%20B%3A%20%E8%BF%87%E5%BA%A6%E6%80%9D%E8%80%83%22%5D%0A%20%20OVER%20--%3E%20F1%5B%22%E5%A4%84%E6%96%B9%3A%20%E7%BD%AE%E4%BF%A1%E6%97%A9%E5%81%9C%2C%20%E7%9C%81%20token%20%E4%B8%8E%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20M%20--%3E%20H%5B%22%E9%9A%BE%E9%A2%98%3A%20%E8%BF%98%E6%B2%A1%E6%83%B3%E9%80%9A%22%5D%0A%20%20H%20--%3E%20UNDER%5B%22%E9%A2%84%E7%AE%97%E5%86%85%E4%B9%B1%E6%94%B6%E5%B0%BE%3A%20%E7%AD%94%E6%A1%88%E6%9C%AA%E6%94%B6%E6%95%9B%22%5D%0A%20%20UNDER%20--%3E%20F2%5B%22%E5%A4%84%E6%96%B9%3A%20%E5%8D%87%E6%A1%A3%20B%20%E6%88%96%E6%8F%92%E5%85%A5%20Wait%20%E7%BB%AD%E5%86%99%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：decode 是逐 token 串行的，思考预算从 512 提到 4096，最坏情况延迟大约涨 8 倍，KV 占用也按比例涨；若一次请求原价 1 分钱，长思考档位可能就是 8 分钱起步。档位设计不是精度微调，是直接写在账单和 SLA 上的数字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>竞赛评测常给足长度，产品 SLA 短，必须单独报两套。用户可见档位应与训练见过的 \\(B\\) 对齐，中间档不要只在网关截断。下一课混合模式：有些请求根本不进思维块。预算只对思维模式有意义。</p><p>用户档位必须是训练见过的 B。隐藏思维与可见摘要分开计 SLA；省 token 不会从对错奖励里长出来。</p><p><span class="marginnote">常见误区：初学者容易把「网关截断」当成一个思考档位——训练时模型从没在 800 token 处被硬掐过，推理时网关却在那里砍断思维链，得到的是分布外的半截推理，准确率掉得比正经小档位更狠。档位要在训练里出现过，而不是上线后靠网关硬切。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>思考预算是测试时缩放的硬顶；自适应是早停。</li><li>训练要见过 \\(B\\)，否则推理截断分布外。</li><li>准确率–延迟曲线比单一准确率更能描述推理模型。</li><li>省 token 必须写进奖励，不会从对错 \\(R\\) 里长出来。</li><li>出处：OpenAI o1；DeepSeek-AI R1；Snell 等测试时计算；Muennighoff 等 s1。</li></ul>',7))])}const C=A(p,[["render",m]]);export{b as __pageData,C as default};
